const string ScriptTag="SPAM";const string BaseRoleTag="[base]";const string SpamChannel="spam";const string SpamProtoVersion="1";const double DefaultRefreshSeconds=5.0;const double DefaultTtlMinutes=60.0;const int DefaultLineGap=0;const float DefaultFontSize=0.7f;IMyRadioAntenna _spamAntenna=null;IMyBroadcastListener _spamListener=null;readonly List<IMyTextPanel>_spamLcds=new List<IMyTextPanel>();readonly Dictionary<string,BaseShipState>_ships=new Dictionary<string,BaseShipState>();double nowSeconds=0.0;double refreshSeconds=DefaultRefreshSeconds;double ttlMinutes=DefaultTtlMinutes;int lineGap=DefaultLineGap;float fontSize=DefaultFontSize;double nextDrawAt=0.0;string statusMessage="";public Program(){Runtime.UpdateFrequency=UpdateFrequency.Update10;_spamListener=IGC.RegisterBroadcastListener(SpamChannel);ScanBlocks();EnsureBaseDefaults();LoadBaseSettings();ScanBlocks();ConfigureLcds();DrawAllLcds();}public void Main(string argument,UpdateType updateSource){nowSeconds+=Runtime.TimeSinceLastRun.TotalSeconds;if(!string.IsNullOrWhiteSpace(argument))HandleArgument(argument);ProcessMessages();PurgeExpiredShips();if(nowSeconds>=nextDrawAt){LoadBaseSettings();ScanBlocks();ConfigureLcds();DrawAllLcds();nextDrawAt=nowSeconds+refreshSeconds;}}void HandleArgument(string argument){string[]parts=(argument??"").Trim().Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);if(parts.Length<2){statusMessage="Cmd: stop/resume/gohome target";return;}string command=parts[0].Trim().ToUpperInvariant();string targetType="";string targetValue="";if(parts.Length==2&&string.Equals(parts[1],"all",StringComparison.OrdinalIgnoreCase)){targetType="ALL";targetValue="*";}else if(parts.Length>=3&&string.Equals(parts[1],"group",StringComparison.OrdinalIgnoreCase)){targetType="GROUP";targetValue=parts[2].Trim();}else if(parts.Length>=3&&string.Equals(parts[1],"ship",StringComparison.OrdinalIgnoreCase)){targetType="SHIP";targetValue=parts[2].Trim();}else{statusMessage="Cmd: use all/group/ship";return;}if(command!="STOP"&&command!="RESUME"&&command!="GOHOME"){statusMessage="Cmd: bad action";return;}SendCommand(targetType,targetValue,command);}void SendCommand(string targetType,string targetValue,string command){if(_spamAntenna==null){statusMessage="Need [spam] antenna.";return;}string payload="SPAM|"+SpamProtoVersion+"|CMD|"+targetType+"|"+targetValue+"|"+command;IGC.SendBroadcastMessage(SpamChannel,payload,TransmissionDistance.TransmissionDistanceMax);statusMessage="Sent "+command+" "+targetType+":"+targetValue;DrawAllLcds();}void ProcessMessages(){if(_spamListener==null)return;while(_spamListener.HasPendingMessage){MyIGCMessage msg=_spamListener.AcceptMessage();if(msg.Tag!=SpamChannel||!(msg.Data is string))continue;string payload=(string)msg.Data;string[]parts=payload.Split('|');if(parts.Length<11)continue;if(!string.Equals(parts[0],"SPAM",StringComparison.OrdinalIgnoreCase))continue;if(!string.Equals(parts[1],SpamProtoVersion,StringComparison.OrdinalIgnoreCase))continue;if(!string.Equals(parts[2],"STATUS",StringComparison.OrdinalIgnoreCase))continue;string shipId=parts[3].Trim();if(shipId.Length==0)continue;BaseShipState state;if(!_ships.TryGetValue(shipId,out state)){state=new BaseShipState();state.ShipId=shipId;_ships[shipId]=state;}state.ShipName=parts[4].Trim();state.Groups=parts[5].Trim();state.Primary=parts[6].Trim();state.Secondary=parts[7].Trim();state.Progress=parts[8].Trim();state.Cargo=parts[9].Trim();state.Battery=parts[10].Trim();state.Distance=parts.Length>11?parts[11].Trim():"-";state.LastSeenSeconds=nowSeconds;}}void PurgeExpiredShips(){double ttlSeconds=Math.Max(60.0,ttlMinutes*60.0);var remove=new List<string>();foreach(var kv in _ships){if(nowSeconds-kv.Value.LastSeenSeconds>ttlSeconds)remove.Add(kv.Key);}for(int i=0;i<remove.Count;i++)_ships.Remove(remove[i]);}void DrawAllLcds(){Echo("SPAM Base\nShips: "+_ships.Count+"\n"+statusMessage);for(int i=0;i<_spamLcds.Count;i++){var lcd=_spamLcds[i];if(lcd==null)continue;string group=ReadLcdGroup(lcd);string text=BuildLcdText(lcd,group);lcd.WriteText(text??"");}}string BuildLcdText(IMyTextPanel lcd,string group){var rows=new List<BaseShipState>();foreach(var kv in _ships){var ship=kv.Value;if(ShipInGroup(ship,group))rows.Add(ship);}rows.Sort((a,b)=>string.Compare(a.ShipName??"",b.ShipName??"",StringComparison.OrdinalIgnoreCase));var sb=new StringBuilder();sb.AppendLine("SPAM Base");sb.AppendLine("Group:"+group);sb.AppendLine();sb.AppendLine(Fit("Ship",12)+" "+Fit("Progress",10)+" "+Fit("Status",18)+" "+Fit("Dist",6)+" "+Fit("Ore",4)+" "+Fit("Bat",4));sb.AppendLine();for(int i=0;i<rows.Count;i++){var ship=rows[i];sb.AppendLine(Fit(ship.ShipName,12)+" "+Fit(FormatProgress(ship.Progress),10)+" "+Fit(FormatStatus(ship),18)+" "+Fit(ship.Distance,6)+" "+Fit(FormatPercent(ship.Cargo),4)+" "+Fit(FormatPercent(ship.Battery),4));for(int gap=0;gap<lineGap;gap++)sb.AppendLine();}if(rows.Count==0)sb.AppendLine("No ships.");if(!string.IsNullOrWhiteSpace(statusMessage)){sb.AppendLine();sb.AppendLine(statusMessage);}return sb.ToString().TrimEnd();}string FormatProgress(string value){if(string.IsNullOrWhiteSpace(value)||value=="-")return"-";return value.Replace(" ","").Trim();}string FormatPercent(string value){if(string.IsNullOrWhiteSpace(value)||value=="-")return"-";return value.Replace("%","").Trim()+"%";}string FormatStatus(BaseShipState ship){string primary=string.IsNullOrWhiteSpace(ship.Primary)?"-":ship.Primary.Trim();string secondary=string.IsNullOrWhiteSpace(ship.Secondary)?"-":ship.Secondary.Trim();if(secondary=="-"||secondary.Length==0)return primary;return primary+" / "+secondary;}string Fit(string text,int width){string value=string.IsNullOrWhiteSpace(text)?"-":text.Trim();if(value.Length>width)return value.Substring(0,width);return value.PadRight(width);}bool ShipInGroup(BaseShipState ship,string group){if(ship==null)return false;if(string.IsNullOrWhiteSpace(group))return true;string[]parts=(ship.Groups??"").Split(',');for(int i=0;i<parts.Length;i++)if(string.Equals(parts[i].Trim(),group,StringComparison.OrdinalIgnoreCase))return true;return false;}string ReadLcdGroup(IMyTextPanel lcd){var map=ParseSimpleSettings(lcd.CustomData);string value;if(map.TryGetValue("group",out value)&&!string.IsNullOrWhiteSpace(value))return value.Trim();return"main";}void ScanBlocks(){_spamAntenna=null;_spamLcds.Clear();var antennas=new List<IMyRadioAntenna>();GridTerminalSystem.GetBlocksOfType(antennas,a=>a.IsSameConstructAs(Me));for(int i=0;i<antennas.Count;i++){var antenna=antennas[i];if(antenna==null)continue;if(HasTag(antenna)){if(_spamAntenna==null)_spamAntenna=antenna;else statusMessage="Warn: multiple [spam] antennas.";}}var lcds=new List<IMyTextPanel>();GridTerminalSystem.GetBlocksOfType(lcds,l=>l.IsSameConstructAs(Me));for(int i=0;i<lcds.Count;i++){var lcd=lcds[i];if(lcd==null)continue;if(HasTag(lcd))_spamLcds.Add(lcd);}}void EnsureBaseDefaults(){var pbMap=ParseSimpleSettings(Me.CustomData);string pbText=Me.CustomData??"";if(!pbMap.ContainsKey("channel")||string.IsNullOrWhiteSpace(pbMap["channel"]))pbText=UpsertSimpleSetting(pbText,"channel",SpamChannel);if(!pbMap.ContainsKey("ttl_minutes")||string.IsNullOrWhiteSpace(pbMap["ttl_minutes"]))pbText=UpsertSimpleSetting(pbText,"ttl_minutes",DefaultTtlMinutes.ToString("0"));if(!pbMap.ContainsKey("refresh_seconds")||string.IsNullOrWhiteSpace(pbMap["refresh_seconds"]))pbText=UpsertSimpleSetting(pbText,"refresh_seconds",DefaultRefreshSeconds.ToString("0"));if(!pbMap.ContainsKey("line_gap")||string.IsNullOrWhiteSpace(pbMap["line_gap"]))pbText=UpsertSimpleSetting(pbText,"line_gap",DefaultLineGap.ToString());if(!pbMap.ContainsKey("font_size")||string.IsNullOrWhiteSpace(pbMap["font_size"]))pbText=UpsertSimpleSetting(pbText,"font_size",DefaultFontSize.ToString("0.0"));Me.CustomData=pbText.TrimEnd();if(_spamAntenna!=null){var antennaMap=ParseSimpleSettings(_spamAntenna.CustomData);string antennaText=_spamAntenna.CustomData??"";if(!antennaMap.ContainsKey("channel")||string.IsNullOrWhiteSpace(antennaMap["channel"]))antennaText=UpsertSimpleSetting(antennaText,"channel",SpamChannel);_spamAntenna.CustomData=antennaText.TrimEnd();}for(int i=0;i<_spamLcds.Count;i++){var lcd=_spamLcds[i];if(lcd==null)continue;var lcdMap=ParseSimpleSettings(lcd.CustomData);string lcdText=lcd.CustomData??"";if(!lcdMap.ContainsKey("group")||string.IsNullOrWhiteSpace(lcdMap["group"]))lcdText=UpsertSimpleSetting(lcdText,"group","main");lcd.CustomData=lcdText.TrimEnd();}}void LoadBaseSettings(){refreshSeconds=DefaultRefreshSeconds;ttlMinutes=DefaultTtlMinutes;lineGap=DefaultLineGap;fontSize=DefaultFontSize;var map=ParseSimpleSettings(Me.CustomData);string value;double d;int n;float f;if(map.TryGetValue("refresh_seconds",out value)&&double.TryParse(value,out d))refreshSeconds=Clamp(d,1.0,60.0);if(map.TryGetValue("ttl_minutes",out value)&&double.TryParse(value,out d))ttlMinutes=Clamp(d,1.0,1440.0);if(map.TryGetValue("line_gap",out value)&&int.TryParse(value,out n))lineGap=Math.Max(0,Math.Min(5,n));if(map.TryGetValue("font_size",out value)&&float.TryParse(value,out f))fontSize=ClampFloat(f,0.4f,3.0f);}void ConfigureLcds(){for(int i=0;i<_spamLcds.Count;i++){var lcd=_spamLcds[i];if(lcd==null)continue;lcd.ContentType=ContentType.TEXT_AND_IMAGE;lcd.Font="Monospace";lcd.FontSize=fontSize;lcd.Alignment=TextAlignment.LEFT;}}Dictionary<string,string>ParseSimpleSettings(string text){var map=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(string.IsNullOrWhiteSpace(text))return map;string[]lines=text.Split('\n');for(int i=0;i<lines.Length;i++){string line=lines[i].Replace("\r","");int eq=line.IndexOf('=');if(eq<=0)continue;string key=line.Substring(0,eq).Trim();string value=line.Substring(eq+1).Trim();if(key.Length==0)continue;map[key]=value;}return map;}string UpsertSimpleSetting(string text,string key,string value){string[]lines=string.IsNullOrWhiteSpace(text)?new string[0]:text.Replace("\r","").Split('\n');var sb=new StringBuilder();bool replaced=false;for(int i=0;i<lines.Length;i++){string line=lines[i];if(line.TrimStart().StartsWith(key+"=",StringComparison.OrdinalIgnoreCase)){sb.AppendLine(key+"="+value);replaced=true;}else if(line.Length>0)sb.AppendLine(line);}if(!replaced)sb.AppendLine(key+"="+value);return sb.ToString().TrimEnd();}bool HasTag(IMyTerminalBlock block){if(block==null)return false;return ContainsIgnoreCase(block.CustomName,ScriptTag)||ContainsIgnoreCase(block.CustomData,ScriptTag);}bool ContainsIgnoreCase(string text,string value){if(string.IsNullOrEmpty(text)||string.IsNullOrEmpty(value))return false;return text.IndexOf(value,StringComparison.OrdinalIgnoreCase)>=0;}double Clamp(double value,double min,double max){if(value<min)return min;if(value>max)return max;return value;}float ClampFloat(float value,float min,float max){if(value<min)return min;if(value>max)return max;return value;}class BaseShipState{public string ShipId="";public string ShipName="";public string Groups="";public string Primary="";public string Secondary="";public string Progress="";public string Cargo="";public string Battery="";public string Distance="";public double LastSeenSeconds=0.0;}